from collections import deque

def pacific_atlantic(heights):
    if not heights:
        return []
    m, n = len(heights), len(heights[0])
    def bfs(starts):
        seen = set(starts)
        q = deque(starts)
        while q:
            i, j = q.popleft()
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n and (ni, nj) not in seen:
                    if heights[ni][nj] >= heights[i][j]:
                        seen.add((ni, nj))
                        q.append((ni, nj))
        return seen
    pacific = bfs([(0, j) for j in range(n)] + [(i, 0) for i in range(m)])
    atlantic = bfs([(m-1, j) for j in range(n)] + [(i, n-1) for i in range(m)])
    return list(pacific & atlantic)
